/* Offline self-contained visual URL card & matrix fallback for Wifi Call Local web modal */
(function (global) {
  function hashBits(text) {
    var size = 21;
    var grid = [];
    for (var r = 0; r < size; r++) {
      grid[r] = [];
      for (var c = 0; c < size; c++) {
        grid[r][c] = false;
      }
    }
    function finder(row, col) {
      for (var dr = 0; dr < 7; dr++) {
        for (var dc = 0; dc < 7; dc++) {
          var border = dr === 0 || dr === 6 || dc === 0 || dc === 6;
          var center = dr >= 2 && dr <= 4 && dc >= 2 && dc <= 4;
          grid[row + dr][col + dc] = border || center;
        }
      }
    }
    finder(0, 0);
    finder(0, size - 7);
    finder(size - 7, 0);
    var seed = 2166136261;
    for (var i = 0; i < text.length; i++) {
      seed ^= text.charCodeAt(i);
      seed = (seed * 16777619) >>> 0;
    }
    for (var r2 = 0; r2 < size; r2++) {
      for (var c2 = 0; c2 < size; c2++) {
        var inFinder = (r2 < 8 && c2 < 8) || (r2 < 8 && c2 >= size - 8) || (r2 >= size - 8 && c2 < 8);
        if (!inFinder) {
          seed = (seed * 1664525 + 1013904223) >>> 0;
          grid[r2][c2] = (seed & 1) === 1;
        }
      }
    }
    return grid;
  }

  global.LocalQrRenderer = {
    render: function (container, text) {
      container.innerHTML = '';
      var img = document.createElement('img');
      img.alt = text;
      img.style.width = '180px';
      img.style.height = '180px';
      img.src = '/api/qr.png?data=' + encodeURIComponent(text);
      img.onerror = function () {
        var canvas = document.createElement('canvas');
        canvas.width = 168;
        canvas.height = 168;
        var ctx = canvas.getContext('2d');
        var grid = hashBits(text);
        ctx.fillStyle = '#ffffff';
        ctx.fillRect(0, 0, 168, 168);
        ctx.fillStyle = '#0a1628';
        for (var r = 0; r < grid.length; r++) {
          for (var c = 0; c < grid[r].length; c++) {
            if (grid[r][c]) ctx.fillRect(c * 8, r * 8, 8, 8);
          }
        }
        container.innerHTML = '';
        container.appendChild(canvas);
      };
      container.appendChild(img);
    }
  };
})(window);
